def energy(t):return sum((j+1)*n for j,n in enumerate(t))
def alpha(n,v):
    out=defaultdict(QQ)
    if n==0:return {}
    for occ,coef in v.items():
        ii=abs(n)-1;aa=list(occ)+[0]*max(0,ii+1-len(occ))
        if n>0:
            if not aa[ii]:continue
            c=n*aa[ii];aa[ii]-=1
        else:c=1;aa[ii]+=1
        out[trim(aa)]+=coef*c
    return clean(out)
@lru_cache(None)
def stress_on(m,occ):
    E=energy(occ);out={}
