    for r in range(-E-abs(m)-2,E+abs(m)+3):
        a,b=m-r,r
        if not a or not b:continue
        if a>0 and b<0:a,b=b,a
        term=alpha(a,alpha(b,{occ:QQ(1)}))
        out=add(out,term,QQ(1)/2)
    return out
